package com.mitahv.mobile.i18n

/**
 * Display-only translations for messages generated by data/model code.
 * Callers must not pass mail bodies, editable values, or arbitrary player-authored text.
 * Template captures are copied verbatim; this never changes request or model values.
 */
class AppMessageTranslator(
    private val chinese: Boolean,
    private val gameTranslate: (String) -> String,
) {
    fun translate(text: String): String {
        if (!chinese && text.none { it in '\u3400'..'\u9fff' }) return text
        val lines = text.split('\n')
        return lines.mapIndexed { index, line ->
            // These original confirmations put an equipment name on a separate line.
            if (index > 0 && lines[index - 1].removeSuffix("\r") in verbatimNameIntroductions) line
            else if (chinese) translateChineseLine(line) else translateLine(line)
        }.joinToString("\n")
    }

    private fun translateChineseLine(line: String): String {
        if (line.endsWith('\r')) return translateChineseLine(line.dropLast(1)) + '\r'
        // Native labels do not always exist as text in the original page.
        nativeChineseLabels[line]?.let { return it }
        abilityNextTier.matchEntire(line)?.let { return "下一等级：${translateChineseLine(it.groupValues[1])}" }
        abilityRequirements.matchEntire(line)?.let { return "需要等级 ${it.groupValues[1]}、${it.groupValues[2]} 技能点" }
        abilityResetCost.matchEntire(line)?.let { return "${it.groupValues[1]} 灵魂碎片" }
        missingSoulFragments.matchEntire(line)?.let { return "还需 ${it.groupValues[1]} 灵魂碎片" }
        if (line in labels) return gameTranslate(line)
        userNameAction.matchEntire(line)?.let {
            return gameTranslate(it.groupValues[1]) + it.groupValues[2]
        }

        val colon = line.indexOfFirst { it == '：' || it == ':' }
        if (colon > 0) {
            val label = line.substring(0, colon)
            val separatorEnd = colon + if (line.getOrNull(colon + 1) == ' ') 2 else 1
            val separator = line.substring(colon, separatorEnd)
            val value = line.substring(separatorEnd)
            if (isVerbatimField(label)) {
                return chineseFieldLabel(label) + separator + value
            }
            // These are generated read-only facts or known field controls. Their
            // values contain game terms/counts, not player-entered names or mail.
            if (label in labels || localizedFieldLabel.matches(label) || summaryTemplates.any { it.pattern.matches(value) }) {
                return "${chineseFieldLabel(label)}：${gameTranslate(value)}"
            }
            return gameTranslate(line)
        }

        fieldValidation.matchEntire(line)?.let {
            return chineseFieldLabel(it.groupValues[1]) + gameTranslate(it.groupValues[2])
        }
        requiredField.matchEntire(line)?.let {
            return gameTranslate("请填写") + chineseFieldLabel(it.groupValues[1])
        }
        localizedFieldLabel.matchEntire(line)?.let { return chineseFieldLabel(line) }
        if (templates.any { it.pattern.matches(line) } || summaryTemplates.any { it.pattern.matches(line) } ||
            charmSlotAction.matches(line)) return gameTranslate(line)
        // Callers mark remaining text as translatable game labels/server feedback.
        return gameTranslate(line)
    }

    private fun chineseFieldLabel(label: String): String = localizedFieldLabel.matchEntire(label)?.let {
        "${it.groupValues[1]} · ${gameTranslate(it.groupValues[2])}"
    } ?: gameTranslate(label)

    private fun translateLine(line: String): String {
        if (line.endsWith('\r')) return translateLine(line.dropLast(1)) + '\r'
        labels[line]?.let { return it }
        templates.firstNotNullOfOrNull { template ->
            template.pattern.matchEntire(line)?.let(template.render)
        }?.let { return it }

        // A generated field summary may contain a user-entered value. Translate its
        // known label, but do not feed that value back through the label dictionary.
        val colon = line.indexOf('：')
        if (colon > 0) {
            val label = line.substring(0, colon)
            val value = line.substring(colon + 1)
            val translatedLabel = englishLabel(label)
            val translatedValue = if (label in verbatimValueLabels || label.endsWith(" · 名称")) value
                else translateSummaryValue(value)
            if (label in labels || translatedLabel != label || translatedValue != value) {
                return "$translatedLabel: $translatedValue"
            }
        }
        return translateSummaryValue(line)
    }

    private fun translateSummaryValue(value: String): String = summaryTemplates.firstNotNullOfOrNull { template ->
        template.pattern.matchEntire(value)?.let(template.render)
    } ?: value

    private data class Template(val pattern: Regex, val render: (MatchResult) -> String)

    private companion object {
        fun template(pattern: String, render: (MatchResult) -> String) = Template(Regex(pattern), render)

        val fieldLabel = Regex("(.+) · (名称|攻击类型|伤害类型)")
        val localizedFieldLabel = Regex("(.+) · (名称|Name|攻击类型|Attack [Tt]ype|Skill [Tt]ype|伤害类型|Damage [Tt]ype|Damage)")
        val fieldValidation = Regex("(.+?)(最多 [0-9]+ 字|请输入整数|不能小于 -?[0-9]+|不能大于 -?[0-9]+)")
        val requiredField = Regex("请填写(.+)")
        val abilityNextTier = Regex("Next:\\s*(.+)")
        val abilityRequirements = Regex("Requires Level ([\\d,]+) and ([\\d,]+) Ability Points?")
        val abilityResetCost = Regex("([\\d,]+) Soul Fragments?")
        val missingSoulFragments = Regex("You need an additional ([\\d,]+) soul fragments?\\.", RegexOption.IGNORE_CASE)
        val nativeChineseLabels = mapOf(
            "General" to "常规",
            "Deprecating I" to "减益魔法 I",
            "Deprecating II" to "减益魔法 II",
            "Supportive I" to "增益魔法 I",
            "Supportive II" to "增益魔法 II",
            "Unlock Slot" to "解锁栏位",
            "Create Monster" to "创建怪物",
            "Feed All" to "全部喂食",
            "Give Happy Pills" to "喂快乐药丸",
            "Chaos" to "混沌",
            "Slot" to "栏位",
            "Species" to "种族",
        )
        val userNameAction = Regex("(重命名 |删除 |Rename |Delete )(.*)")
        val charmSlotAction = Regex("(Attach Charm|Destroy Charm|Replace Charm|Replace Pouch|Repair Pouch) · Charm Slot [0-9]+")
        val verbatimNameIntroductions = setOf("将此受保护装备加入本次选择？", "将受保护装备设为本次可选：")
        val gainedLabel = Regex("获得 (.+)")
        val verbatimValueLabels = setOf("装备名称", "怪物名称", "名称", "收件人", "寄信人", "主题", "正文", "融合至", "牺牲装备", "附件")
        val englishVerbatimValueLabels = setOf("equipment name", "monster name", "name", "recipient", "sender", "to", "from",
            "subject", "message", "body", "fuse into", "sacrificed equipment", "attachment", "attachments")

        fun isVerbatimField(label: String): Boolean = label in verbatimValueLabels ||
            label.lowercase() in englishVerbatimValueLabels || label.endsWith(" · 名称") || label.endsWith(" · Name")

        fun englishLabel(label: String): String = labels[label]
            ?: fieldLabel.matchEntire(label)?.let { "${it.groupValues[1]} · ${labels[it.groupValues[2]]}" }
            ?: gainedLabel.matchEntire(label)?.let { "Receive ${it.groupValues[1]}" }
            ?: label

